/**
 * @file test_lcd.c
 * @brief Simple LCD test program for ESP32-S3 Eye
 */

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <stdint.h>
#include <string.h>

#define FB_DEVICE "/dev/fb0"
#define SCREEN_WIDTH 240
#define SCREEN_HEIGHT 240
#define BPP 16  /* RGB565 */

/**
 * @brief Fill framebuffer with a color
 */
int fill_screen(uint16_t color)
{
    int fd;
    uint16_t buffer[SCREEN_WIDTH * SCREEN_HEIGHT];
    ssize_t ret;

    /* Fill buffer with color */
    for (int i = 0; i < SCREEN_WIDTH * SCREEN_HEIGHT; i++) {
        buffer[i] = color;
    }

    /* Open framebuffer device */
    fd = open(FB_DEVICE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open framebuffer");
        return -1;
    }

    /* Write buffer to framebuffer */
    ret = write(fd, buffer, sizeof(buffer));
    if (ret < 0) {
        perror("Failed to write framebuffer");
        close(fd);
        return -1;
    }

    printf("Wrote %zd bytes to framebuffer\n", ret);
    close(fd);
    return 0;
}

/**
 * @brief Main function
 */
int main(int argc, char *argv[])
{
    printf("LCD Test Program\n");
    printf("Screen: %dx%d, %d bpp\n", SCREEN_WIDTH, SCREEN_HEIGHT, BPP);

    /* Fill with red */
    printf("Filling screen with RED...\n");
    fill_screen(0xF800);  /* RGB565 red */
    sleep(2);

    /* Fill with green */
    printf("Filling screen with GREEN...\n");
    fill_screen(0x07E0);  /* RGB565 green */
    sleep(2);

    /* Fill with blue */
    printf("Filling screen with BLUE...\n");
    fill_screen(0x001F);  /* RGB565 blue */
    sleep(2);

    /* Fill with white */
    printf("Filling screen with WHITE...\n");
    fill_screen(0xFFFF);  /* RGB565 white */
    sleep(2);

    printf("LCD test completed!\n");
    return 0;
}

